<template>
<section class="stock-dot-swarm" aria-label="Stock research agent swarm"><header><div><h3>Agent swarm</h3><p>{{ participants.analysts.length }} researchers · {{ participants.traders.length }} simulated investors</p></div><select :value="focus" aria-label="Select a stock agent" @change="$emit('select',$event.target.value)"><option value="">All agents</option><optgroup v-for="panel in panels" :key="panel.id" :label="panel.label"><option v-for="node in panel.nodes" :key="node.id" :value="node.id">{{ node.label }}</option></optgroup></select></header>
<div ref="stage" class="swarm-stage"><div class="swarm-panels">
  <section v-for="panel in panels" :key="panel.id" :class="['swarm-panel',panel.id]" :data-swarm-panel="panel.id"><header><h4>{{ panel.label }}</h4><span>{{ panel.nodes.length }}{{ panel.planned?' queued':'' }}</span></header>
    <svg :ref="el=>{if(el)canvases[panel.id]=el}" viewBox="0 0 300 350" role="group" :aria-label="panel.label+' agent dots'"><g v-for="node in panel.nodes" :key="node.id" :class="['stock-dot',{selected:focus===node.id,speaking:isSpeaking(node.id),receiving:isReceiving(node.id),working:node.lifecycle?.state==='running',queued:node.planned}]" :style="{'--dot-color':node.color,'--dot-delay':node.delay+'s','--drift-x':node.driftX+'px','--drift-y':node.driftY+'px'}" role="button" tabindex="0" :aria-label="`${node.label} · ${node.status}`" :aria-pressed="focus===node.id" @click="$emit('select',node.id)" @keydown.enter="$emit('select',node.id)" @keydown.space.prevent="$emit('select',node.id)"><title>{{ node.label }} · {{ node.status }}</title><circle class="dot-hit" :cx="node.x" :cy="node.y" r="21"/><g class="dot-drift"><circle class="dot-halo" :cx="node.x" :cy="node.y" r="17"/><circle class="dot-ring" :cx="node.x" :cy="node.y" r="14"/><circle class="dot-point" :cx="node.x" :cy="node.y" r="9"/></g><text v-if="focus===node.id||active?.author===node.id" :x="Math.min(190,node.x+14)" :y="node.y+28">{{ node.label.slice(0,23) }}</text></g><text v-if="!panel.nodes.length" x="150" y="175" text-anchor="middle" class="swarm-empty">Waiting for recorded agents</text></svg>
  </section>
</div><svg class="connection-overlay" :viewBox="`0 0 ${bounds.width} ${bounds.height}`" aria-hidden="true"><g><path v-for="edge in routedEdges" :key="edge.id" :d="edge.path" :class="['swarm-link',edge.kind,{selected:edge.source===focus||edge.target===focus,transmitting:activity.some(a=>a.event.id===edge.eventId)}]"><title>{{ edge.label }}</title></path></g><g v-for="item in activity" :key="item.key"><circle v-for="edge in routedEdges.filter(e=>e.eventId===item.event.id)" :key="edge.id" class="packet" r="3.4" opacity="0"><animateMotion :path="edge.path" :dur="motionDuration+'s'" repeatCount="1" fill="freeze"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.1;.8;1" :dur="motionDuration+'s'" repeatCount="1" fill="freeze"/></circle></g></svg></div>
<footer><span>{{ allNodes.find(n=>n.id===focus)?.label||'Select a dot to follow its messages.' }}</span><button v-if="focus" @click="$emit('select','')">Show all</button><span v-else>Peer exchanges · shared research topics</span></footer></section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {swarmPanels,scatterSwarm,swarmRelationships} from '../utils/stockSwarm.mjs'
const props=defineProps({participants:{type:Object,required:true},roles:{type:Array,default:()=>[]},events:{type:Array,default:()=>[]},focus:String,active:Object,activity:{type:Array,default:()=>[]},motionDuration:{type:Number,default:.55}})
defineEmits(['select'])
const stage=ref(null),canvases={},positions={},geometry=ref({}),bounds=reactive({width:900,height:400})
const panels=computed(()=>swarmPanels(props.participants,props.roles).map(panel=>{const nodes=scatterSwarm(panel.people,positions[panel.id]||{}).map(node=>({...node,panel:panel.id}));positions[panel.id]=Object.fromEntries(nodes.map(n=>[n.id,{x:n.x,y:n.y}]));return {...panel,nodes}}))
const allNodes=computed(()=>panels.value.flatMap(p=>p.nodes))
const relationships=computed(()=>swarmRelationships(allNodes.value,props.events))
const routedEdges=computed(()=>relationships.value.map(edge=>{const a=geometry.value[edge.source],b=geometry.value[edge.target];if(!a||!b)return null;const bend=Math.min(36,Math.abs(b.x-a.x)*.12);return {...edge,path:`M ${a.x} ${a.y} Q ${(a.x+b.x)/2} ${(a.y+b.y)/2-bend} ${b.x} ${b.y}`}}).filter(Boolean))
const isSpeaking=id=>props.activity.some(a=>a.event.author===id)||props.active?.author===id
const isReceiving=id=>props.activity.some(a=>a.event.recipients.includes(id))
let observer
async function measure(){await nextTick();if(!stage.value)return;const root=stage.value.getBoundingClientRect();bounds.width=Math.max(1,root.width);bounds.height=Math.max(1,root.height);const next={};for(const panel of panels.value){const rect=canvases[panel.id]?.getBoundingClientRect();if(!rect)continue;const scale=Math.min(rect.width/300,rect.height/350),left=rect.left-root.left+(rect.width-300*scale)/2,top=rect.top-root.top+(rect.height-350*scale)/2;for(const node of panel.nodes)next[node.id]={x:left+node.x*scale,y:top+node.y*scale}}geometry.value=next}
watch(()=>allNodes.value.map(n=>n.id).join('|'),measure)
onMounted(()=>{observer=new ResizeObserver(measure);observer.observe(stage.value);measure()})
onBeforeUnmount(()=>observer?.disconnect())
</script>
<style scoped>
.stock-dot-swarm{border:1px solid var(--research-line);border-radius:8px;overflow:hidden;background:#fff}.stock-dot-swarm>header{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid var(--research-line)}h3{font-size:15px;font-weight:550;margin:0 0 2px}.stock-dot-swarm>header p{font-size:11px;color:var(--research-muted);margin:0}select{font-size:11px;max-width:43%;padding:8px;border:1px solid var(--research-line);border-radius:5px;color:var(--research-muted);background:#fff;min-height:36px}.swarm-stage{position:relative;padding:10px}.swarm-panels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.swarm-panel{border:1px solid var(--research-line);border-radius:6px;overflow:hidden;background:radial-gradient(ellipse at center,#ef762408,transparent 70%);min-width:0}.swarm-panel>header{display:flex;justify-content:space-between;gap:5px;align-items:center;padding:9px 10px;border-bottom:1px solid var(--research-line);min-height:36px}.swarm-panel h4{font-size:11px;font-weight:550;margin:0;color:var(--research-ink)}.swarm-panel>header span{font-size:10px;color:var(--research-muted);white-space:nowrap}.swarm-panel>svg{display:block;width:100%;height:292px;position:relative;z-index:2}.connection-overlay{position:absolute;inset:0;width:100%;height:100%;z-index:3;pointer-events:none;overflow:hidden}.swarm-link{fill:none;stroke:#7d9bac;stroke-width:.9;opacity:.23}.swarm-link.topic{stroke:#cd966b;stroke-dasharray:2 5;opacity:.3}.swarm-link.peer{stroke:#899db1;opacity:.17}.swarm-link.selected{stroke:#ef8a45;stroke-width:1.5;opacity:.8}.swarm-link.transmitting{stroke:#ff984d;stroke-width:1.8;opacity:.9;filter:drop-shadow(0 0 3px #ff7b3545)}.packet{fill:#ffab63;filter:drop-shadow(0 0 3px #ef7624)}.stock-dot{cursor:pointer;outline:none}.dot-hit{fill:transparent}.dot-halo{fill:var(--dot-color);opacity:.15;filter:blur(2px)}.dot-point{fill:var(--dot-color);stroke:#fff;stroke-width:.7;filter:drop-shadow(0 0 4px var(--dot-color));animation:swarm-breathe 2.8s ease-in-out infinite;animation-delay:var(--dot-delay)}.dot-ring{fill:none;stroke:var(--dot-color);opacity:0;stroke-width:1.1}.dot-drift{animation:swarm-drift 4.8s ease-in-out infinite;animation-delay:var(--dot-delay)}.stock-dot.selected .dot-ring{opacity:1;stroke:#e57625;stroke-width:1.7}.stock-dot.speaking .dot-ring,.stock-dot.receiving .dot-ring{opacity:.9;animation:swarm-speak 1.2s ease-out}.stock-dot.working .dot-ring{opacity:.6;animation:swarm-working 2s ease-in-out infinite}.stock-dot.queued .dot-point{opacity:.42;filter:none;animation:none}.stock-dot.queued .dot-halo{opacity:.04}.stock-dot:focus-visible .dot-hit{stroke:#b35319;stroke-width:2;fill:none}.stock-dot text{fill:var(--research-ink);font-size:13px;paint-order:stroke;stroke:#fff;stroke-width:4px}.swarm-empty{fill:var(--research-muted);font-size:13px}.stock-dot-swarm>footer{display:flex;justify-content:space-between;gap:10px;padding:9px 15px;min-height:36px;border-top:1px solid var(--research-line);font-size:10px;color:var(--research-muted)}footer button{border:0;background:none;padding:0;color:#a85d24;cursor:pointer;font-size:11px}.stock-dark .stock-dot-swarm{background:#111923}.stock-dark .stock-dot-swarm select{background:#142434}.stock-dark .swarm-panel{background:radial-gradient(ellipse at center,#f477350a,transparent 70%),#101923}.stock-dark .stock-dot text{stroke:#101923}.stock-dark .dot-point{stroke:#172331}.stock-dark .swarm-link{stroke:#80a3bd;opacity:.27}.stock-dark .swarm-link.topic{stroke:#b48661;opacity:.29}.stock-dark .swarm-link.selected,.stock-dark .swarm-link.transmitting{stroke:#ff9b58;opacity:.9}@keyframes swarm-breathe{50%{opacity:.65;filter:drop-shadow(0 0 7px var(--dot-color))}}@keyframes swarm-drift{50%{transform:translate(var(--drift-x),var(--drift-y))}}@keyframes swarm-speak{0%{r:12;opacity:.9}100%{r:23;opacity:.12}}@keyframes swarm-working{50%{r:18;opacity:.3}}@media(max-width:700px){.swarm-panels{grid-template-columns:repeat(2,minmax(0,1fr))}.swarm-panel.research{grid-column:1/-1;grid-row:1}.swarm-panel.research>svg{height:245px}.swarm-panel>svg{height:245px}.stock-dot-swarm>header{padding:12px}.swarm-panel>header{padding:8px}.stock-dot text{font-size:14px}.stock-dot-swarm>footer{font-size:9px}}@media(prefers-reduced-motion:reduce){.dot-point,.dot-drift,.dot-ring{animation:none!important}.packet{display:none}.swarm-link.transmitting{filter:none}}
</style>
